// coupled-subsystem simulation sketch for: MOOSE Framework
const subs = [
  {name:'power', x:0.625, k:0.133},
  {name:'thermal', x:0.773, k:0.121},
  {name:'structural', x:0.73, k:0.156},
];
for (let t = 0; t < 60; t++) {
  for (const s of subs) { s.x += s.k * (1 - s.x) - 0.015 * s.x; }
}
const fin = subs.map(s => +s.x.toFixed(4));
console.log(JSON.stringify({subsystems: subs.length, steps: 60,
  finalState: fin, converged: fin.every(v => v > 0 && v < 1.5),
  topic: 'MOOSE Framework'}));

